flow_id?: string,
// ID of a previous generation. For image/video/audio, set exactly one of content_asset_id or generation_id.
generation_id?: string,
// Text content for modality 'text'. Required for it.
inline_text?: string,
// Optional display label for the node.
label?: string,
// The kind of static asset to add.
modality: "image" | "video" | "audio" | "text",
}): Promise<// MutationPayload
//
// The result of a canvas mutation: creative_add_flow_node or creative_connect_flow_nodes.
{
// CanvasSummary
// default: null
canvas_summary?: {
// Node Types
node_types: { [key: string]: integer },
// Total Edges
total_edges: integer,
// Total Nodes
total_nodes: integer,
[key: string]: any,
},
// Created Nodes
// default: null
created_nodes?: Array<
// FlowNode
//
// A node creative_add_flow_node created, projected to the fields worth reporting back.
//
// creative_add_flow_node only ever creates a generation node, never a static-asset or
// avatar-reference one, so this does not need to cover those. Canvas-only
// details (position, model_parameters, ...) are intentionally left out —
// additionalProperties still allows them, so a caller reading one back does
// not fail validation over it.
{
// Id
id: string,
// Label
label?: string, // default: null
// Model Id
model_id?: string, // default: null
// Prompt
prompt?: string, // default: null
// Type
type?: string, // default: null
[key: string]: any,
}
>,
// Edges
//
// Edges created or already present on the affected nodes.
// default: null
edges?: Array<
