sourcePort: string,
// Target
target: string,
// Targetport
targetPort: string,
[key: string]: any,
}
>,
// Errors
errors?: string[], // default: null
// Flow Created
flow_created?: boolean, // default: null
// Flow Id
//
// Pass this back to keep working on the same flow.
