// Message
message?: string, // default: null
// Node Ids
//
// IDs of the nodes creative_add_flow_node created.
node_ids?: string[], // default: null
// Success
success?: boolean, // default: null
// Unconnected Required Ports
//
// Required input ports with no edge yet. Wire each with creative_connect_flow_nodes, using this exact port value as target_port, before creative_run_flow_nodes.
// default: null
unconnected_required_ports?: Array<
// RequiredPort
//
// An input port on a created node that must be wired before the node can run.
{
