kind: "image" | "video" | "audio" | "text",
[key: string]: any,
}
>,
// Poll After Seconds
//
// Present only while running. Seconds to wait before calling creative_get_flow_run_status again.
poll_after_seconds?: integer, // default: null
// Results
//
// One entry per generation creative_run_flow_nodes started, in trigger order. media/pending are the view-friendly projection of the same run; read this instead when you need a node_id or per-variation success.
// default: null
results?: Array<
// NodeRunTrigger
//
// One generation a run started. creative_run_flow_nodes triggers one of these per variation.
{
// Error
error?: string, // default: null
// Node Id
node_id: string,
// Session Id
session_id?: string, // default: null
// Success
success: boolean,
[key: string]: any,
}
>,
// Session Id
//
// The first session in this run. Prefer session_ids, which covers all of them.
session_id?: string, // default: null
// Session Ids
//
// One session per variation. Pass all of them to creative_get_flow_run_status.
session_ids?: string[], // default: null
// Status
status?: string, // default: null
// RunNodesSummary
//
// Counts for what the run started: nodes vs the takes the user gets. Any count reported to the user comes from here.
// default: null
summary?: {
// Failed
failed: integer,
// Generations By Node
generations_by_node: { [key: string]: integer },
// Generations Started
generations_started: integer,
// Nodes Run
nodes_run: integer,
[key: string]: any,
},
// Transcripts
//
// Finished speech-to-text generations, with the transcript inline, alongside the language and source audio. Text has no media URL, so this — not `media` — is where a transcription's result lands. Each carries a `download_url` for the text as a .txt file; one too long to carry inline is also cut short and marked `truncated`.
// default: null
transcripts?: Array<
// TranscriptItem
//
// One finished speech-to-text generation.
//
// The transcript *is* the content, so it rides inline rather than behind a
// signed URL — until it outgrows what a chat client should carry, at which
// point ``text`` is cut short and ``download_url`` serves the rest.
// ``download_url`` comes with every transcript, long or short, so a caller
// with no view can always hand the user the file. Word-level timings ride
// the same way: inline up to a cap, with ``words_download_url`` for the rest.
{
// Char Count
//
// Full length before truncation, so the view can say how much it is not showing.
char_count?: integer, // default: null
// Download Url
//
// Short-lived URL to the full transcript as a .txt file. Offer it to the user whenever they want the transcript as a file, and when `text` was truncated fetch it to read the whole thing rather than pasting a transcript that long back into the conversation. Absent for silent audio and for transcripts finished before the text was stored for download.
download_url?: string, // default: null
// Generation Id
generation_id: string,
// Language Code
//
// Detected language, when the engine reported one.
language_code?: string, // default: null
// Language Probability
language_probability?: number, // default: null
// Model Id
model_id?: string, // default: null
// ReferenceThumb
//
// The audio this was transcribed from, with a short-lived URL, whether the user uploaded it or an upstream node produced it. Always shown alongside the transcript.
// default: null
source?: {
// Kind
kind: "image" | "video" | "audio",
// Url
url: string,
[key: string]: any,
},
// Spoken Duration Secs
//
// When speech stops in the source, not the file's own length — the source may run on well past the last word.
spoken_duration_secs?: number, // default: null
// Text
//
// The transcript. Empty string for a recording with no speech in it — never omitted, so the view can say so explicitly.
text: string,
// Truncated
truncated?: boolean, // default: false
// Word Count
//
// Total words with timings, so the view can say how many are not shown inline.
word_count?: integer, // default: null
// Words
//
// Word-level start/end timings in seconds, in spoken order — what captions, subtitles and word highlighting need. Capped at a few hundred entries; when `words_truncated` is true the full list is at `words_download_url`. Absent when the engine reported no timings.
// default: null
words?: Array<
// TranscriptWord
//
// One word of a transcript with when it is spoken, in seconds from the start of the source.
{
// End
end: number,
// Speaker Id
speaker_id?: string, // default: null
// Start
start: number,
// Text
text: string,
// Type
//
// Scribe's token kind. Only words are sent; spacing and audio events are dropped, so the view can rely on this being `word`.
type?: "word", // default: "word"
[key: string]: any,
}
>,
// Words Download Url
//
// Short-lived URL to every word with its timing as JSON: {"words": [{"text", "start", "end", "speaker_id"?}]}. Fetch it to build subtitles or captions for the whole recording rather than pasting a long word list into the conversation. Absent for silent audio and for transcripts finished before word timings were stored.
words_download_url?: string, // default: null
// Words Truncated
words_truncated?: boolean, // default: false
[key: string]: any,
}
>,
// Url
//
// Canvas page for the user. Carries the view_state_id as a query parameter, which is how a view recovers it after a reload; use flow_url for a clean link.
url?: string, // default: null
// View Kind
//
// For the view only — which view renders this result. Present for a speech generation, whose view adds a voice switcher and a pager over the takes generated so far on top of the media.
view_kind?: "speech_generation", // default: null
// ViewNotice
//
// For the view only — a message about the view's own build.
// default: null
view_notice?: {
// Level
level: "subtle" | "blocking",
// Message
message: string,
[key: string]: any,
},
// View State Id
//
// For the view only — pass it to creative_get_view_state and creative_save_view_state so it can rehydrate after a reload. Present only when this call originates a new view; absent on a status poll, since the view already holds the id from the payload it first mounted with.
view_state_id?: string, // default: null
[key: string]: any,
}>;
